run:
(root) => {
    const isl = root.querySelector('.isl');
    let hold = 0;
    let big = false;
    const set = (v) => {
      big = v;
      isl.classList.toggle('big', v);
    };
    isl.addEventListener('click', () => {
      hold = Date.now() + 2500;
      set(!big);
    });
    const tick = () => {
      if (!root.isConnected) return;
      if (!root.dataset.paused && Date.now() > hold) set(!big);
      setTimeout(tick, big ? 2300 : 1300);
    };
    setTimeout(tick, 800);
  }

